package agent_tool

// Input schemas of the supplement tools (design spec §9.2). Every schema is a
// strict object (additionalProperties=false) and every id is a decimal string
// (D29); only assertion stepIndex is a number.
const (
	schemaContextRead = `{"type":"object","properties":{"mode":{"type":"string","enum":["post_batch","incremental_design"]},"batchId":{"type":"string","pattern":"^[0-9]+$"},"requirementIds":{"type":"array","items":{"type":"string","pattern":"^[0-9]+$"}}},"required":["mode"],"additionalProperties":false}`

	schemaCasePropose = `{"type":"object","properties":{"cases":{"type":"array","minItems":1,"maxItems":5,"items":{"type":"object","properties":{"title":{"type":"string","minLength":1},"description":{"type":"string"},"priority":{"type":"string","enum":["P0","P1","P2","P3"]},"preconditions":{"type":"string"},"testData":{"type":"object"},"requirementIds":{"type":"array","minItems":1,"items":{"type":"string","pattern":"^[0-9]+$"}},"steps":{"type":"array","minItems":1,"maxItems":30,"items":{"type":"object","properties":{"action":{"type":"string","minLength":1},"expected":{"type":"string"},"data":{"type":"string"}},"required":["action"],"additionalProperties":false}},"assertions":{"type":"array","minItems":1,"maxItems":30,"items":{"type":"object","properties":{"stepIndex":{"type":"integer","minimum":0},"kind":{"type":"string","enum":["ui","api","db","text"]},"target":{"type":"string"},"expression":{"type":"string","minLength":1},"expected":{"type":"string"}},"required":["kind"],"additionalProperties":false}},"confidence":{"type":"string","enum":["high","medium","low"]},"rationale":{"type":"string","maxLength":4000}},"required":["title","steps","assertions","requirementIds"],"additionalProperties":false}}},"required":["cases"],"additionalProperties":false}`

	schemaAffectedCases = `{"type":"object","properties":{"cases":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","properties":{"caseNodeId":{"type":"string","pattern":"^[0-9]+$"},"confidence":{"type":"string","enum":["high","medium","low"]},"reason":{"type":"string","minLength":1},"source":{"type":"string","enum":["requirement","code"]},"requirementIds":{"type":"array","items":{"type":"string","pattern":"^[0-9]+$"}},"codeRefs":{"type":"array","maxItems":20,"items":{"type":"object","properties":{"path":{"type":"string","minLength":1},"line":{"type":"integer","minimum":1},"reason":{"type":"string"}},"required":["path"],"additionalProperties":false}}},"required":["caseNodeId","confidence","reason","source"],"additionalProperties":false}}},"required":["cases"],"additionalProperties":false}`

	schemaEscalate = `{"type":"object","properties":{"title":{"type":"string","minLength":1},"detail":{"type":"string","maxLength":4000},"requirementIds":{"type":"array","minItems":1,"items":{"type":"string","pattern":"^[0-9]+$"}},"escalations":{"type":"array","minItems":1,"maxItems":3,"items":{"type":"object","properties":{"title":{"type":"string","minLength":1},"detail":{"type":"string","maxLength":4000},"requirementIds":{"type":"array","minItems":1,"items":{"type":"string","pattern":"^[0-9]+$"}}},"required":["title","requirementIds"],"additionalProperties":false}}},"anyOf":[{"required":["escalations"]},{"required":["title","requirementIds"]}],"additionalProperties":false}`

	schemaFinish = `{"type":"object","properties":{"summary":{"type":"string","maxLength":2000}},"additionalProperties":false}`
)
